# >>> CHOICES
if [[ -n "$ARGC_COMPLETIONS_ROOT" && -f "$ARGC_COMPLETIONS_ROOT/utils/_argc_utils.sh" ]]; then
    . "$ARGC_COMPLETIONS_ROOT/utils/_argc_utils.sh"
fi

_choice_nft_cmds() {
    local -a words=("${argc__positionals[@]:0:$(( ${#argc__positionals[@]} - 1 ))}")
    local count=${#words[@]}
    if [[ $count -eq 0 ]]; then
        _helper_nft_verbs
        return 0
    fi
    local verb=${words[0]}
    local object=${words[1]:-}
    if [[ $verb == monitor ]]; then
        _helper_nft_monitor "$count" "$object"
        return 0
    fi
    if [[ $count -eq 1 ]]; then
        _helper_nft_objects "$verb"
        return 0
    fi
    local offset=2
    if [[ $object == ct ]]; then
        if [[ $count -eq 2 ]]; then
            printf '%s\n' helper timeout expectation
            return 0
        fi
        offset=3
    fi
    local family="" i
    for ((i = offset; i < count; i++)); do
        if _helper_nft_is_family "${words[i]}"; then
            family=${words[i]}
            offset=$((i + 1))
            break
        fi
    done
    local rest=$((count - offset))
    if [[ $rest -eq 0 ]]; then
        if [[ -z $family ]]; then
            _helper_nft_families
        fi
        if [[ $object != table ]]; then
            _helper_nft_tables "$family"
        fi
        return 0
    fi
    if [[ $rest -eq 1 ]]; then
        case $object in
        chain | rule) _helper_nft_chains "$family" "${words[offset]}" ;;
        set | map | element) _helper_nft_sets_maps "$family" "${words[offset]}" ;;
        esac
    fi
}

_helper_nft_chains() {
    local family=$1 table=$2
    nft -j list chains 2>/dev/null | jq -b -r --arg f "$family" --arg t "$table" '
        .nftables[]? | select(type == "object" and has("chain")) | .chain
        | select(($f == "" or .family == $f) and .table == $t)
        | "\(.name)\t\(.family) \(.table)"'
}

_helper_nft_families() {
    printf '%s\t%s\n' \
        ip 'IPv4 address family' \
        ip6 'IPv6 address family' \
        inet 'Internet (IPv4/IPv6) address family' \
        arp 'ARP address family' \
        bridge 'Bridge address family' \
        netdev 'Netdev address family'
}

_helper_nft_is_family() {
    case $1 in
    ip | ip6 | inet | arp | bridge | netdev) return 0 ;;
    esac
    return 1
}

_helper_nft_monitor() {
    local count=$1 object=$2
    if [[ $count -eq 1 ]]; then
        printf '%s\t%s\n' \
            new 'Only new objects' \
            destroy 'Only destroyed objects' \
            trace 'Packets with nftrace enabled'
        printf '%s\n' tables chains sets rules elements ruleset
    elif [[ $count -eq 2 && ( $object == new || $object == destroy ) ]]; then
        printf '%s\n' tables chains sets rules elements ruleset
    fi
}

_helper_nft_objects() {
    case $1 in
    add | delete | destroy)
        printf '%s\n' table chain rule set map element flowtable counter quota limit ct
        ;;
    insert | replace)
        printf '%s\n' rule
        ;;
    create)
        printf '%s\n' chain element flowtable
        ;;
    list)
        printf '%s\n' ruleset hooks \
            tables table chains chain rules rule sets set maps map \
            flowtables flowtable counters counter quotas quota limits limit ct
        ;;
    flush)
        printf '%s\n' ruleset table chain set map
        ;;
    reset)
        printf '%s\n' rules rule element set map counter quota limit
        ;;
    rename)
        printf '%s\n' chain
        ;;
    get)
        printf '%s\n' element
        ;;
    esac
}

_helper_nft_sets_maps() {
    local family=$1 table=$2 kind
    for kind in set map; do
        nft -j list "${kind}s" 2>/dev/null | jq -b -r --arg f "$family" --arg t "$table" --arg k "$kind" '
            .nftables[]? | select(type == "object" and has($k)) | .[$k]
            | select(($f == "" or .family == $f) and .table == $t)
            | "\(.name)\t\($k) \(.family) \(.table)"'
    done
}

_helper_nft_tables() {
    local family=$1
    nft -j list tables 2>/dev/null | jq -b -r --arg f "$family" '
        .nftables[]? | select(type == "object" and has("table")) | .table
        | select($f == "" or .family == $f)
        | "\(.name)\t\(.family)"'
}

_helper_nft_verbs() {
    printf '%s\t%s\n' \
        add 'Add a new object' \
        insert 'Insert a rule at the beginning of a chain' \
        replace 'Replace a rule' \
        create 'Like add, but fail if the object exists' \
        delete 'Delete an object' \
        destroy 'Delete an object, do not fail if it does not exist' \
        list 'List objects' \
        flush 'Remove objects' \
        reset 'Reset stateful information' \
        rename 'Rename an object' \
        get 'Get an element' \
        describe 'Show information about an expression or data type' \
        monitor 'Monitor netlink events'
}
# <<< CHOICES

command eval "$(argc --argc-eval "$0" "$@")"
